class Solution:
    def maximumBobPoints(self, numArrows: int, aliceArrows: List[int]) -> List[int]:
        best_score = 0
        best_mask = 0

        def dfs(i, arrows, score, mask):
            nonlocal best_score, best_mask
            if i == 12:
                if score > best_score:
                    best_score, best_mask = score, mask
                return
            cost = aliceArrows[i] + 1
            if arrows >= cost:
                dfs(i + 1, arrows - cost, score + i, mask | (1 << i))
            dfs(i + 1, arrows, score, mask)

        dfs(0, numArrows, 0, 0)
        bob = [0] * 12
        for i in range(12):
            if best_mask >> i & 1:
                bob[i] = aliceArrows[i] + 1
                numArrows -= bob[i]
        bob[0] += numArrows
        return bob

